  (2495, 'Oct 2025 - OpenVC.xlsx', 'b2venture', 'Venture Fund', 'Pre-Seed, Seed, Series A', 'https://www.b2venture.vc/', 'We invest in (AI-enabled) B2C- and B2B-oriented businesses amongst others in the fields of fintech, supply chain, sustainability, horizontal AI, robotics and digital health.', '', '', '', 'Unterstrasse 6, 9000 St. Gallen, Switzerland', 'Unterstrasse 6', null, null, '', '', '', 0, 0, 'We invest in (AI-enabled) B2C- and B2B-oriented businesses amongst others in the fields of fintech, supply chain, sustainability, horizontal AI, robotics and digital health. Invests in: Switzerland,Germany,Austria,Poland,UK,France,Spain,Portugal,Netherlands,Belgium,Italy,Czech Republic,Hungary First cheque: $500,000 - $3,000,000', null),
  (2496, 'Oct 2025 - OpenVC.xlsx', 'Babajide Tella', 'Solo angel', 'Pre-Seed, Seed, Series A', '', 'I invest in early-stage startups led by mission-driven founders solving high-impact problems in Nigeria and African markets. My focus areas include technology, consumer goods, financial services, retail, and emerging sectors like AI and blockchain. I’m especially interested in businesses with a strong execution team and a clear growth path.', '', '', '', 'New York, USA', 'New York', 40.7128, -74.006, '', '', '', 0, 0, 'I invest in early-stage startups led by mission-driven founders solving high-impact problems in Nigeria and African markets. My focus areas include technology, consumer goods, financial services, retail, and emerging sectors like AI and blockchain. I’m especially interested in businesses with a strong execution team and a clear growth path. Invests in: Ghana,Kenya,Nigeria,South Africa,USA,UK,Saudi Arabia,UAE First cheque: $5,000 - $50,000', null),
  (2497, 'Oct 2025 - OpenVC.xlsx', 'Babak Kia', 'Solo angel', 'Pre-Seed, Seed, Series A', '', 'I invest in founders focused on applying technology to a business solution, who either have a lot of proof on the technology side, or good proof on the GTM side.', '', '', '', 'Boston, MA, USA', 'Boston', 42.3601, -71.0589, '', '', '', 0, 0, 'I invest in founders focused on applying technology to a business solution, who either have a lot of proof on the technology side, or good proof on the GTM side. Invests in: USA,UAE First cheque: $25,000 - $100,000', null),
