  (2971, 'Oct 2025 - OpenVC.xlsx', 'Francois-Gerald Hochard', 'Solo angel', 'Pre-Seed', '', 'I invest in scientific and technical founders building in AI, cybersecurity, quantum computing, defense tech or industrial automation. I look for strong IP or research roots and high-impact use cases.', '', '', '', '69006 Lyon, France', 'France', 48.8566, 2.3522, '', '', '', 0, 0, 'I invest in scientific and technical founders building in AI, cybersecurity, quantum computing, defense tech or industrial automation. I look for strong IP or research roots and high-impact use cases. Invests in: France First cheque: $1,000 - $5,000', null),
  (2972, 'Oct 2025 - OpenVC.xlsx', 'Frank Cid', 'Solo angel', 'Pre-Seed, Seed, Series A, Series B, Series C, Growth', 'https://www.28.ventures/', 'I invest in high-growth startups in tech, media, AI, and fintech, focusing on scalable businesses with strong monetization and exit potential. My ideal scenario is to help my portfolio company to an IPO within 24 months after I write the first check', '', '', '', 'New York, USA', 'New York', 40.7128, -74.006, '', '', '', 0, 0, 'I invest in high-growth startups in tech, media, AI, and fintech, focusing on scalable businesses with strong monetization and exit potential. My ideal scenario is to help my portfolio company to an IPO within 24 months after I write the first check Invests in: Canada,USA,Hong Kong,Indonesia,Japan,Malaysia,Singapore,Taiwan,Thailand First cheque: $100,000 - $1,000,000', null),
  (2973, 'Oct 2025 - OpenVC.xlsx', 'Frederico Serras Gago', 'Solo angel', 'Pre-Seed, Seed', '', 'I invest in B2B and B2C SaaS', '', '', '', 'Lisbon, 1250-140 Portugal', 'Lisbon', 38.7223, -9.1393, '', '', '', 0, 0, 'I invest in B2B and B2C SaaS Invests in: Portugal First cheque: $5,000 - $50,000', null),
  (2974, 'Oct 2025 - OpenVC.xlsx', 'Freesearch Ventures', 'Venture Fund', 'Series A, Seed', 'https://freesearch.vc/', 'We invest from $300K to $1M in late Seed and early Series A startups with focus on Fintech, AI, SaaS, E-commerce, Marketplaces, and B2B software. Confirmed Product market fit and a fast-growing market is important. Revenue from $500K ARR and strong growth indicators.', '', '', '', 'Singapore', 'Singapore', 1.3521, 103.8198, '', '', '', 0, 0, 'We invest from $300K to $1M in late Seed and early Series A startups with focus on Fintech, AI, SaaS, E-commerce, Marketplaces, and B2B software. Confirmed Product market fit and a fast-growing market is important. Revenue from $500K ARR and strong growth indicators. Invests in: USA First cheque: $200,000 - $750,000', null),
